messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "An envelope has arrived from Pittsburgh. Alma's daughter sent a receipt for a recorded interview. The line copied her reply: 'I know that voice. Play it again.'"
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hey, it's Phil. I'm in Pittsburgh now, just off the coach. Listen, about tomorrow—van's booked for the couch, right? I want to nail down the pickup time and make sure I know which hallway we're dragging it through. I'll be at your place by noon, tops."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil pockets the contents of the crew fare envelope. The envelope is empty.",
   "evening": "Phil lets the evening go by in bed alone.",
   "what_you_said": "Rita. I hear you. About Alma. I'll call her from the terminal tomorrow, after I'm off the coach. I'll ask her what she wants to hear. I'll just... listen. I'll do it from a payphone with a three-minute limit and I'll do it. Goodnight.",
   "your_last_intention": "Be on that coach at first light. Be in Pittsburgh by ten. Be at my sister's door by noon. Move the goddamn couch. That's the whole evening. That's the whole point of the week.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil calls his sister in Pittsburgh. The van is still booked for Wednesday.",
   "what_you_said": "Yeah. It's me. I'm at the station. Listen, I don't want to do this at nine a.m. with the driver looking at me like I'm a prop in his commercial. What time does the guy pull up? And—yeah, the short hall, the one by the kitchen, the couch faces the window, I know, I know, I already know. I just need the number on the door and the time. That's it. That's the call. ...Yeah. Goodnight, Alma.",
   "your_last_intention": "Get the pickup time in my head. Get the hallway width in my head. Know tomorrow without having to figure it out at nine a.m. with a stranger's van idling in the driveway.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil closes the curtains and spends the afternoon in bed.",
   "evening": "Phil attends the festival party.",
   "what_you_said": "Okay.",
   "your_last_intention": "Be vertical and in a lit room before I go back upstairs. Feel the floor under my feet. Feel the weight of the keys under my palms without having to make a sound. Let the evening be something I was inside of, not something I slept through with the curtains drawn. I don't need to play. I don't need to perform. I need to be a body in a room where the lights are on and the air is moving and it is seven o'clock and the evening is still happening whether I'm in it or not.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "get_up": "Get up and choose what to do today.",
  "stay_in_bed": "Turn over and stay in bed.",
  "listen_again": "Stay still and listen for the second backfire."
 }
}
